  var status=document.getElementById('register-status');
  var TO='spark2026@example.com';
  var defs=[
    {id:'reg-name',msg:'Please enter your name.'},
    {id:'reg-email',msg:'Please enter your email address.'},
    {id:'reg-college',msg:'Please enter your college.'},
    {id:'reg-event',msg:'Please choose an event.'}
  ];
  function setError(el,msg){
    var err=document.getElementById(el.id+'-err');
    if(err)err.textContent=msg;
    if(msg){el.setAttribute('aria-invalid','true');}
    else{el.removeAttribute('aria-invalid');}
  }
  function check(def){
    var el=document.getElementById(def.id);
    if(!el)return true;
    var v=(el.value||'').trim();
    if(!v){setError(el,def.msg);return false;}
    if(el.type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)){
      setError(el,'Please enter a valid email address.');
      return false;
    }
    setError(el,'');
    return true;
  }
  function setStatus(text,isError){
    if(!status)return;
    status.textContent=text;
    status.classList.toggle('is-error',!!isError);
  }
  for(var i=0;i<defs.length;i++){
    (function(def){
      var el=document.getElementById(def.id);
      if(!el)return;
      var evt=el.tagName==='SELECT'?'change':'input';
      el.addEventListener(evt,function(){
        if(el.getAttribute('aria-invalid')==='true')check(def);
      });
    })(defs[i]);
  }
