    if(firstBad){
      setStatus('Please fix the highlighted fields and try again.',true);
      firstBad.focus();
      return;
    }
    var name=document.getElementById('reg-name').value.trim();
    var email=document.getElementById('reg-email').value.trim();
    var college=document.getElementById('reg-college').value.trim();
    var ev=document.getElementById('reg-event').value;
    var body=[
      'Spark 2026 registration',
      '',
      'Name: '+name,
      'Email: '+email,
      'College: '+college,
      'Event: '+ev
    ].join('\r\n');
    var url='mailto:'+TO+'?subject='+encodeURIComponent('Spark 2026 registration: '+ev)+'&body='+encodeURIComponent(body);
    setStatus('Almost done: your email app should open with your details. Press send to finish registering. If nothing opens, email '+TO+' with your name, college and event.',false);
    window.location.href=url;
  });
})();
